.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-desktop) !important}
@media(max-width: 976px) {.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-tablet) !important}}
@media(max-width: 767px) {.eon8-live-page .uag-blocks-common-selector {z-index:var(--z-index-mobile) !important}}
.eon8-live-page .uk-navbar-left img {
    height: 60px;
    width: auto;
    object-fit: contain;
    transition: height 0.35s ease;
    display: block;
    margin-top:-10px;
}
.eon8-live-page .uk-navbar {
    display: flex !important;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    position: relative;
    z-index: 1;
}
.eon8-live-page .uk-navbar-left {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 80px !important;
    flex-wrap: nowrap;
}
.eon8-live-page .uk-navbar-right {
    display: flex !important;
    align-items: center;
    margin-left: auto;
}
.eon8-live-page .uk-navbar-nav > li > .uk-navbar-dropdown {
    left: 50% !important;
    transform: translateX(-50%) !important;
    right: auto !important;
}
.eon8-live-page .uk-navbar-nav {
    display: flex !important;
    align-items: center;
    flex-direction: row;
    gap: 5px;
    list-style: none;
    margin: 0;
    padding: 0;
}
.eon8-live-page .uk-navbar-nav > li {
    display: flex;
    align-items: center;
    position: relative;
    white-space: nowrap;
}
.eon8-live-page .uk-navbar-nav > li > a {
    display: flex;
    align-items: center;
    padding: 6px 10px;
    font-size: 14px;
    line-height: 1;
    text-decoration: none;
    position: relative;
}
.eon8-live-page .uk-navbar-nav > li > a::after {
    content: "";
    position: absolute;
    bottom: 0;
    left: 10px;
    right: 10px;
    height: 2px;
    transform: scaleX(0);
    transition: transform 0.3s ease;
    transform-origin: left;
}
.eon8-live-page .uk-navbar-nav > li > a:hover::after {
    transform: scaleX(1);
}
@media (max-width: 1024px) {.eon8-live-page .uk-navbar-left img {
        height: 50px;
    }
.eon8-live-page .uk-navbar-nav {
        gap: 5px;
    }}
@media (max-width: 768px) {.eon8-live-page .uk-navbar-left img {
        height: 45px;
    }
.eon8-live-page .uk-navbar-nav {
        display: none !important;
    }}
@media (max-width: 480px) {.eon8-live-page .uk-navbar-left img {
        height: 38px;
    }}
.eon8-live-page #responsive-form {
    max-width: 80%;
    margin: 0 auto;
    width: 100%;
    padding: 20px;
    border: 1px solid #25125247;
    border-radius: 7px;
    background: url("/wp-content/uploads/2022/01/form-bg-1.png");
    background-position: right bottom;
    background-size: cover;
    background-repeat: no-repeat;
    box-shadow: 0 0 10px #251252;
}
.eon8-live-page .ba_inr_cnt h2 {
    color: white;
}
.eon8-live-page section.banner_inr:before {
    background-image: linear-gradient(to right bottom, #f5822000, #ff637c00, #e273c700, #8990ea00, #009fda00);
}
.eon8-live-page .single-feature {
    padding: 66px 20px 0;
    min-height: 265px;
    margin-bottom: 30px;
}
.eon8-live-page .table>tbody>tr>th, .eon8-live-page .table>tbody>tr>td {
    padding: 15px 10px !important;
    text-align: center;
    align-items: center;
    border: 0px;
}
.eon8-live-page .bg-color, .eon8-live-page table tr td:nth-child(1) {
    background: #f58220 !important;
    color: #fff;
    font-size: 17px;
    font-weight: 600;
}
.eon8-live-page th {
    font-size: 17px;
    text-align: center;
}
.eon8-live-page i.fa-times {
    color: red;
}
.eon8-live-page i.fa-check {
    color: green;
}
.eon8-live-page .social_media a.fb {
    background: #3B5998;
}
.eon8-live-page .social_media a.tw {
    background: #00ACED;
}
.eon8-live-page .social_media a.gp {
    background: #DD4B39;
}
.eon8-live-page .social_media a.inst {
    background: #859BB0;
}
.eon8-live-page .social_media a.pin {
    background: #CB2027;
}
.eon8-live-page .social_media a.li {
    background: #007BB6;
}
.eon8-live-page .pricing .fa-check {
    color: #65B688;
}
.eon8-live-page .pricing .fa-times {
    color: #D55B4E;
}
.eon8-live-page .social_media a {
    display: inline-block;
    width: 24px;
    height: 24px;
    line-height: 24px;
    margin-right: 15px;
    border-radius: 3px;
    color: #fff;
    text-align: center;
}
.eon8-live-page .ba_inr_cnt h1 {
    font-size: 2.5rem;
}
.eon8-live-page .faq {
    background: #00a0da;
    padding-bottom: 70px;
    background-color: rgba(13, 81, 137, 0.9);
    background-repeat: no-repeat;
    background-size: cover;
    background-position: left;
    background-image: url("/wp-content/uploads/2020/10/faq-digital-marketing-agency.jpg");
    padding-bottom: 60px;
}
.eon8-live-page .faq .sec_tit h2 {
    color: #FFF !important;
}
.eon8-live-page .ba_inr_cnt {
    margin-top: 50px;
}
.eon8-live-page .list-nft ul li {
    list-style: none;
    margin-bottom: 10px;
}
.eon8-live-page .ba_inr_cnt ul li {
    color: #FFF;
    font-size: 16px;
    line-height: 28px;
}
.eon8-live-page .list-nft ul li i {
    margin-right: 10px;
}
.eon8-live-page .list-nft ul {
    padding-left: 0;
}
.eon8-live-page .single-feature h2 {
    color: #fff;
    position: relative;
    font-size: 20px;
    font-weight: 500;
    text-transform: capitalize;
    padding-bottom: 13px;
    margin-bottom: 16px;
}
.eon8-live-page .single-feature h3 {
    color: #fff;
    position: relative;
    font-size: 20px;
    font-weight: 500;
    text-transform: capitalize;
    padding-bottom: 13px;
    margin-bottom: 16px;
}
